package com.bank.palindrome;

import java.util.logging.*;

public class PalindromeDemo {
    private static final Logger log = Logger.getLogger("Palindrome");
    static {
        ConsoleHandler h = new ConsoleHandler();
        h.setFormatter(new SimpleFormatter());
        log.setUseParentHandlers(false);
        log.addHandler(h);
    }

    public static void main(String[] args) {
        PalindromeService service = new PalindromeService();
        log.info(() -> "madam     → " + service.isPalindrome("madam"));
        log.info(() -> "SAV2001   → " + service.isPalindrome("SAV2001"));
        log.info(() -> "Nurses run→ " + service.isPalindrome("Nurses run")); // normalised
    }
}

// ─── Would be in service/PalindromeService.java ───
class PalindromeService {
    boolean isPalindrome(String raw) {
        String s = raw.toLowerCase().replaceAll("[^a-z0-9]", ""); // normalise
        int n = s.length();
        return java.util.stream.IntStream.range(0, n / 2)          // first half only
            .allMatch(i -> s.charAt(i) == s.charAt(n - 1 - i));    // compare mirrors
    }
}
